/// `PersonalizePostTemplateViewHelper::dto`: the post template with its
/// sections by position.
async fn post_template_dto<C: ConnectionTrait>(db: &C, t: post_templates::Model) -> ApiResult<PostTemplate> {
    let sections = post_template_sections::Entity::find()
        .filter(post_template_sections::Column::PostTemplateId.eq(t.id))
        .order_by_asc(post_template_sections::Column::Position)
        .order_by_asc(post_template_sections::Column::Id)
        .all(db)
        .await?;
    Ok(PostTemplate {
        id: t.id,
        label: t.label,
        label_translation_key: t.label_translation_key,
        position: i64::from(t.position),
        can_be_deleted: t.can_be_deleted,
        sections: sections.into_iter().map(Into::into).collect(),
    })
}

/// `PersonalizeGroupTypeViewHelper::dto`: the group type with its roles by
/// position.
async fn group_type_dto<C: ConnectionTrait>(db: &C, t: group_types::Model) -> ApiResult<GroupType> {
    let roles = group_type_roles::Entity::find()
        .filter(group_type_roles::Column::GroupTypeId.eq(t.id))
        .order_by_asc(group_type_roles::Column::Position)
        .order_by_asc(group_type_roles::Column::Id)
        .all(db)
        .await?;
    Ok(GroupType {
        id: t.id,
        label: t.label,
        label_translation_key: t.label_translation_key,
        position: i64::from(t.position),
        roles: roles.into_iter().map(Into::into).collect(),
    })
}

/// The modules on `page_id` with their positions, by position.
async fn page_modules<C: ConnectionTrait>(db: &C, page_id: Id) -> ApiResult<Vec<TemplatePageModule>> {
    let rows = module_template_page::Entity::find()
        .filter(module_template_page::Column::TemplatePageId.eq(page_id))
        .order_by_asc(module_template_page::Column::Position)
        .order_by_asc(module_template_page::Column::ModuleId)
        .find_also_related(modules::Entity)
        .all(db)
        .await?;
    Ok(rows.into_iter().filter_map(|(pivot, m)| Some(TemplatePageModule::new(m?, pivot.position))).collect())
}

/// `module_id` as placed on `page_id`; 404 if it isn't on the page.
async fn page_module<C: ConnectionTrait>(db: &C, page_id: Id, module_id: Id) -> ApiResult<TemplatePageModule> {
    let (pivot, module) = module_template_page::Entity::find()
        .filter(module_template_page::Column::TemplatePageId.eq(page_id))
        .filter(module_template_page::Column::ModuleId.eq(module_id))
        .find_also_related(modules::Entity)
        .one(db)
        .await?
        .and_then(|(p, m)| m.map(|m| (p, m)))
        .ok_or_else(ApiError::not_found)?;
    Ok(TemplatePageModule::new(module, pivot.position))
}

