// ---------------------------------------------------------------- validation

/// A name or label the body must carry: `required|string|max:255`.
fn required_text(v: &mut Validator, field: &str, value: Option<String>) -> Option<String> {
    let value = clean(value);
    if v.required(field, &value) {
        v.max_len(field, value.as_deref(), 255);
    }
    value
}

/// A name or label the body may carry (PATCH): absent leaves it unchanged,
/// present must pass `required|string|max:255`.
fn optional_text(v: &mut Validator, field: &str, value: Option<String>) -> Option<String> {
    let present = value.is_some();
    let value = clean(value);
    if present && v.required(field, &value) {
        v.max_len(field, value.as_deref(), 255);
    }
    value
}

/// A new `position`: an integer of at least 1.
fn position(v: &mut Validator, value: Option<i64>) -> Option<i32> {
    v.between("position", value, 1, i64::from(i32::MAX));
    value.and_then(|p| i32::try_from(p).ok())
}

