#[utoipa::path(
    post,
    path = "/account/templates",
    operation_id = "createTemplate",
    tag = "Account",
    summary = "Create a contact template",
    request_body = TemplateCreate,
    responses((status = 201, description = "The created template.", body = Template), (status = 401, description = "No valid session or token (`unauthenticated`)."), (status = 403, description = "`forbidden`, `csrf_token_mismatch`, `email_not_verified`, `token_ability_missing`, `password_confirmation_required` or `signup_disabled`."), (status = 422, description = "`validation_failed` (with `errors`), `storage_limit_exceeded` or `vault_user_limit_reached`.")),
    extensions(("x-permission" = json!("account:admin")), ("x-inventory" = json!(["R299"])), ("x-services" = json!(["CreateTemplate", "CreateTemplatePage"])))
)]
pub async fn create_template(
    State(state): State<AppState>,
    Auth(id): Auth,
    Json(body): Json<TemplateCreate>,
) -> ApiResult<(StatusCode, Json<Template>)> {
    access::administrator(&id)?;
    let mut v = Validator::new();
    let name = required_text(&mut v, "name", body.name);
    v.finish()?;
    // CreateTemplate creates the contact information page (CreateTemplatePage).
    let tx = state.db.begin().await?;
    let template = CreateTemplate {
        account_id: id.user.account_id,
        author_id: id.user.id,
        name,
        name_translation_key: None,
        can_be_deleted: None,
    }
    .execute(&tx)
    .await?;
    tx.commit().await?;
    Ok((StatusCode::CREATED, Json(template.into())))
}

