pub async fn update_template(
    State(state): State<AppState>,
    Auth(id): Auth,
    Path(template_id): Path<Id>,
    Json(body): Json<TemplateUpdate>,
) -> ApiResult<Json<Template>> {
    access::administrator(&id)?;
    let template = find_template(&state, &id, template_id).await?;
    let mut v = Validator::new();
    let name = required_text(&mut v, "name", body.name);
    v.finish()?;
    let template = UpdateTemplate {
        account_id: id.user.account_id,
        author_id: id.user.id,
        template_id: template.id,
        name: name.unwrap_or_default(),
    }
    .execute(&state.db)
    .await?;
    Ok(Json(template.into()))
}

