#[utoipa::path(
    get,
    path = "/account/templates/{template_id}/pages/{template_page_id}",
    operation_id = "getTemplatePage",
    tag = "Account",
    summary = "Get a template page with its modules",
    params(("template_id" = i64, Path), ("template_page_id" = i64, Path)),
    responses((status = 200, description = "The page.", body = TemplatePageDetail), (status = 401, description = "No valid session or token (`unauthenticated`)."), (status = 403, description = "`forbidden`, `csrf_token_mismatch`, `email_not_verified`, `token_ability_missing`, `password_confirmation_required` or `signup_disabled`."), (status = 404, description = "Doesn't exist or isn't visible to the user (`not_found`).")),
    extensions(("x-permission" = json!("account:member")), ("x-inventory" = json!(["R306"])), ("x-services" = json!([])))
)]
pub async fn get_template_page(
    State(state): State<AppState>,
    Auth(id): Auth,
    Path((template_id, template_page_id)): Path<(Id, Id)>,
) -> ApiResult<Json<TemplatePageDetail>> {
    let page = find_page(&state, &id, template_id, template_page_id).await?;
    let modules = page_modules(&state.db, page.id).await?;
    // The contact information page takes the modules reserved to it, the
    // other pages take the rest.
    let fitting = modules::Entity::find()
        .filter(modules::Column::AccountId.eq(id.user.account_id))
        .filter(modules::Column::ReservedToContactInformation.eq(page.r#type.as_deref() == Some("contact_information")))
        .order_by_asc(modules::Column::Id)
        .all(&state.db)
        .await?;
    let available_modules = fitting
        .into_iter()
        .map(|m| TemplatePageAvailableModule {
            already_used: modules.iter().any(|on_page| on_page.id == m.id),
            name: m.name,
            name_translation_key: m.name_translation_key,
            id: m.id,
            r#type: m.r#type,
            reserved_to_contact_information: m.reserved_to_contact_information,
            can_be_deleted: m.can_be_deleted,
            pagination: m.pagination.map(i64::from),
        })
        .collect();
    Ok(Json(TemplatePageDetail {
        name: page.name,
        name_translation_key: page.name_translation_key,
        id: page.id,
        template_id: page.template_id,
        slug: page.slug,
        r#type: page.r#type,
        position: page.position.map(i64::from),
        can_be_deleted: page.can_be_deleted,
        modules,
        available_modules,
    }))
}

