#[utoipa::path(
    get,
    path = "/account/group-types",
    operation_id = "listGroupTypes",
    tag = "Account",
    summary = "List group types with their roles",
    responses((status = 200, description = "The group types.", body = GroupTypeList), (status = 401, description = "No valid session or token (`unauthenticated`)."), (status = 403, description = "`forbidden`, `csrf_token_mismatch`, `email_not_verified`, `token_ability_missing`, `password_confirmation_required` or `signup_disabled`.")),
    extensions(("x-permission" = json!("account:member")), ("x-inventory" = json!(["R269"])), ("x-services" = json!([])))
)]
pub async fn list_group_types(State(state): State<AppState>, Auth(id): Auth) -> ApiResult<Json<GroupTypeList>> {
    let rows = group_types::Entity::find()
        .filter(group_types::Column::AccountId.eq(id.user.account_id))
        .order_by_asc(group_types::Column::Position)
        .order_by_asc(group_types::Column::Id)
        .all(&state.db)
        .await?;
    let mut data = Vec::with_capacity(rows.len());
    for t in rows {
        data.push(group_type_dto(&state.db, t).await?);
    }
    Ok(Json(GroupTypeList { data }))
}

