/// The operations of this module.
pub fn routes() -> OpenApiRouter<AppState> {
    OpenApiRouter::new()
        .routes(routes!(list_templates, create_template))
        .routes(routes!(get_template, update_template, delete_template))
        .routes(routes!(create_template_page))
        .routes(routes!(get_template_page, update_template_page, delete_template_page))
        .routes(routes!(add_template_page_module, update_template_page_module, remove_template_page_module))
        .routes(routes!(list_account_modules))
        .routes(routes!(list_post_templates, create_post_template))
        .routes(routes!(update_post_template, delete_post_template))
        .routes(routes!(create_post_template_section))
        .routes(routes!(update_post_template_section, delete_post_template_section))
        .routes(routes!(list_group_types, create_group_type))
        .routes(routes!(update_group_type, delete_group_type))
        .routes(routes!(create_group_type_role))
        .routes(routes!(update_group_type_role, delete_group_type_role))
}
